核心就是提取 `result` 字段，因此实现就很简单：

```ts
const transformERNIEBotStream = (chunk: ChatResp): StreamProtocolChunk => {
  const finished = chunk.is_end;
  // 判断下结束，返回 stop 标记
  if (finished) {
    return { data: chunk.finish_reason || 'stop', id: chunk.id, type: 'stop' };
  }

  // 有 result ，返回 result 结果，类型为 text
  if (chunk.result) {
    return { data: chunk.result, id: chunk.id, type: 'text' };
  }
};
```

以上就完成了 wenxin 的流式协议转换

### chat 方法中接入

有了上述方法以后，在chat层实现就很简单了，
```ts
 async chat(payload: ChatStreamPayload, options?: ChatCompetitionOptions) {
    const result: AsyncIterable<ChatResp> = await this.client.chat(
      { messages: payload.messages, stream: true },
      payload.model,
    );

    // 1. 获取 ReadableStream 实例
    const wenxinStream = WenxinResultToStream(result);

    // 2. 利用 tee 实现分流，这样消费 prod 和 debug 流就不会互相影响
    const [prod, useForDebug] = wenxinStream.tee();

    // 3. 加一个 debug 标记，这样在终端就能看到原始流的信息
    if (process.env.DEBUG_WENXIN_CHAT_COMPLETION === '1') {
      debugStream(useForDebug).catch();
    }

    // 4. 将原始的 ReadableStream 转为我们处理过的流
    const stream = WenxinStream(prod, options?.callback);

    // 5. 将流以 Response 的方式进行返回
    return StreamingResponse(stream, { headers: options?.headers });
  }
```

