// 注册聚合

export const useRegisterChatHotkeys = () => {
  const { enableScope, disableScope } = useHotkeysContext();

  // System
  useOpenChatSettingsHotkey();

  // Layout
  useToggleLeftPanelHotkey();
  useToggleRightPanelHotkey();
  useToggleZenModeHotkey();

  // Conversation
  useRegenerateMessageHotkey();
  useSaveTopicHotkey();
  useAddUserMessageHotkey();

  useEffect(() => {
    enableScope(HotkeyScopeEnum.Chat);
    return () => disableScope(HotkeyScopeEnum.Chat);
  }, []);

  return null;
};
```

## 作用域实现机制

快捷键作用域（Scope）是整个快捷键系统的核心控制机制，它解决了"在正确的上下文中提供正确的快捷键"的问题，以下详细介绍其实现原理和流程：

### 作用域基本概念

作用域本质上是快捷键的分组标识符，用于控制哪些快捷键在哪些界面环境中可用。我们的系统定义了两个主要作用域：

1. **全局作用域（GLOBAL_HOTKEY_SCOPE = 'global'）**：应用全局可用的快捷键
2. **聊天作用域（CHAT_HOTKEY_SCOPE = 'chat'）**：仅在聊天界面可用的快捷键

此外，每个快捷键ID也自动成为一个独立作用域，用于精细控制单个快捷键的启用/禁用状态。

### 作用域注册与生命周期

1. **应用初始化阶段**：

   ```tsx
   // 在应用根组件中注册HotkeysProvider
   <HotkeysProvider initiallyActiveScopes={[HotkeyScopeEnum.Global]}>
     <App />
   </HotkeysProvider>
   ```

   此时只有全局作用域（'global'）中的快捷键是激活状态

2. **进入聊天页面**：

   ```tsx
   // 在聊天页面组件中
   const { enableScope } = useHotkeysContext();

   useEffect(() => {
     // 启用聊天作用域
     enableScope(HotkeyScopeEnum.Chat);

     // 组件卸载时可以选择性地禁用（我们的实现中依赖React组件树结构，未显式禁用）
     // return () => disableScope(HotkeyScopeEnum.Chat);
   }, []);
   ```

3. **快捷键定义与作用域关联**：

   ```ts
	export const HOTKEYS_REGISTRATION: HotkeyRegistration = [
	  {
	    group: HotkeyGroupEnum.Essential,
	    id: HotkeyEnum.Search,
	    keys: combineKeys([KeyEnum.Mod, 'k']),
		// 定义一个全局搜索快捷键
	    scopes: [HotkeyScopeEnum.Global],
	  },
	  {
	    group: HotkeyGroupEnum.Essential,
	    id: HotkeyEnum.ToggleLeftPanel,
	    keys: combineKeys([KeyEnum.Mod, KeyEnum.Alt, KeyEnum.Left]),
		// 定义一个仅在聊天界面可用的快捷键
	    scopes: [HotkeyScopeEnum.Chat],
	  },
	  {
		group: HotkeyGroupEnum.Conversation,
		id: HotkeyEnum.AddUserMessage,
		keys: combineKeys([KeyEnum.Alt, KeyEnum.Enter]),
		// 不通过 Scope 模式激活
	  }
   ```

### 作用域控制流程详解

1. **应用启动时**：

- HotkeysProvider 初始化快捷键系统
- initiallyActiveScopes 属性激活全局作用域
- 全局作用域的快捷键（如搜索、切换面板等）立即可用

2. **布局组件中的作用域注册**：

- 全局布局（`(main)/_layout/Desktop/index.tsx`）提供全局快捷键作用域
- 聊天布局（`chat/_layout/Desktop/index.tsx`）通过 RegisterHotkeys 组件注册聊天作用域

3. **快捷键处理流程**：

- 用户按下组合键
- 系统检查该组合键对应的处理函数
- 验证该处理函数关联的作用域是否处于激活状态
- 只有作用域激活时才执行相应功能

### 自定义Hook简化作用域管理

我们的 `useHotkeyById` hook 封装了作用域管理细节：

```tsx
export const useHotkeyById = (hotkeyId: HotkeyId, callback: HotkeyCallback, options?: Options) => {
  // 从用户配置获取快捷键值
  const hotkey = useUserStore(settingsSelectors.getHotkeyById(hotkeyId));

  const ref = useHotkeys(hotkey, callback, {
    // 默认设置
    enableOnFormTags: true,
    preventDefault: true,

    // 合并传入的选项
    ...options,

    // 关键：自动将快捷键ID添加到作用域列表
    // 这样每个快捷键既属于其功能组（如全局/聊天），又可以单独控制
    scopes: uniq([hotkeyId, ...(item?.scopes || []), ...(_options?.scopes || [])]),
  });

  return { id: hotkeyId, ref };
};
```

