const InputArea = memo<InputAreaProps>(({ onSend, value, loading, onChange }) => {
  const { enableScope, disableScope } = useHotkeysContext();

  // ...其他代码

  return (
    <div className={styles.textareaContainer}>
      <TextArea
        // ...其他属性
        onBlur={(e) => {
          onChange?.(e.target.value);
          disableScope(HotkeyEnum.AddUserMessage); // 当输入框失去焦点时禁用相关快捷键
        }}
        onFocus={() => {
          enableScope(HotkeyEnum.AddUserMessage); // 当输入框获得焦点时启用相关快捷键
        }}
        // ...其他事件处理
      />
    </div>
  );
});
```

这种实现展示了快捷键作用域控制的几个关键特性：

1. **状态感知的作用域控制**：

- 只在输入框获得焦点时启用 `AddUserMessage` 快捷键作用域
- 当输入框失去焦点时自动禁用该作用域，防止快捷键误触发

2. **UI交互驱动的作用域管理**：

- 将快捷键作用域的生命周期与UI组件的交互状态（如焦点）绑定
- 不同于页面级作用域，这种控制可以精确到单个UI元素的状态

3. **防止冲突的精细控制**：

- 通过精确控制作用域的启用/禁用时机，确保快捷键只在适当的上下文中激活
- 解决了同一快捷键在不同上下文中可能产生冲突的问题

4. **用户体验优化**：

- 确保快捷键行为符合用户直觉，只在用户关注特定UI元素时激活相关快捷键
- 提供了更符合预期的交互体验，减少意外操作

这种细粒度的作用域控制机制使得快捷键系统能够适应复杂的UI状态，为用户提供上下文相关的键盘交互体验，同时保持整体系统的可维护性和一致性。

## 设置面板实现

数据驱动型设置面板，新增快捷键后不需要更新，会自动按 const 中的排序和分组进行渲染

```tsx
'use client';

import { Form, HotkeyInput, type ItemGroup } from '@lobehub/ui';
import isEqual from 'fast-deep-equal';
import { memo } from 'react';
import { useTranslation } from 'react-i18next';

import { HOTKEYS_REGISTRATION } from '@/const/hotkeys';
import { FORM_STYLE } from '@/const/layoutTokens';
import hotkeyMeta from '@/locales/default/hotkey';
import { useUserStore } from '@/store/user';
import { settingsSelectors } from '@/store/user/selectors';
import { HotkeyGroupEnum, HotkeyItem } from '@/types/hotkey';

type SettingItemGroup = ItemGroup;

const HOTKEY_SETTING_KEY = 'hotkey';

const HotkeySetting = memo(() => {
  const { t } = useTranslation(['setting', 'hotkey']);
  const [form] = Form.useForm();

  const settings = useUserStore(settingsSelectors.currentSettings, isEqual);
  const [setSettings] = useUserStore((s) => [s.setSettings]);

  const mapHotkeyItem = (item: HotkeyItem) => {
    const hotkeyConflicts = Object.entries(settings.hotkey)
      .map(([key, value]) => {
        if (key === item.id) return false;
        return value;
      })
      .filter(Boolean) as string[];

    return {
      children: (
        <HotkeyInput
          disabled={item.nonEditable}
          hotkeyConflicts={hotkeyConflicts}
          resetValue={item.keys}
        />
      ),
      desc: hotkeyMeta[item.id].desc ? t(`${item.id}.desc`, { ns: 'hotkey' }) : undefined,
      label: t(`${item.id}.title`, { ns: 'hotkey' }),
      name: [HOTKEY_SETTING_KEY, item.id],
    };
  };

  // 构建设置分组...

  return (
    <Form
      form={form}
      initialValues={settings}
      items={[system, conversation, layout]}
      itemsType={'group'}
      onValuesChange={setSettings}
      variant={'pure'}
      {...FORM_STYLE}
    />
  );
});
```

