### 4. 更新辅助函数

```typescript
// apps/desktop/src/main/modules/updater/utils.ts
import semver from 'semver';

/**
 * 判断是否需要应用更新而非仅渲染层更新
 * @param currentVersion 当前版本
 * @param nextVersion 新版本
 * @returns 是否需要应用更新
 */
export const shouldUpdateApp = (currentVersion: string, nextVersion: string): boolean => {
  // 如果版本号包含 .app 后缀，强制进行应用更新
  if (nextVersion.includes('.app')) {
    return true;
  }
  
  try {
    // 解析版本号
    const current = semver.parse(currentVersion);
    const next = semver.parse(nextVersion);
    
    if (!current || !next) return true;
    
    // 主版本号或次版本号变更时，需要进行应用更新
    if (current.major !== next.major || current.minor !== next.minor) {
      return true;
    }
    
    // 仅修订版本号变更，优先进行渲染层热更新
    return false;
  } catch (error) {
    // 解析失败时，默认进行应用更新
    return true;
  }
};
```

### 5. IPC 服务实现

```typescript
// apps/desktop/src/main/services/UpdaterSrv.ts
import { IPCEvent } from '@lobechat/electron-server-ipc';
import { mainLogger as logger } from '@/utils/logger';
import type { App } from '@/core/App';

export default class UpdaterService {
  private app: App;

  constructor(app: App) {
    this.app = app;
  }

  /**
   * 检查更新
   */
  @IPCEvent('updater:check-update', 'client')
  async checkForUpdates() {
    logger.info('[UpdaterSrv] Check for updates requested');
    await this.app.updaterManager.checkForUpdates();
    return { success: true };
  }

  /**
   * 下载更新
   */
  @IPCEvent('updater:download-update', 'client')
  async downloadUpdate() {
    logger.info('[UpdaterSrv] Download update requested');
    await this.app.updaterManager.downloadUpdate();
    return { success: true };
  }

  /**
   * 安装更新
   */
  @IPCEvent('updater:install-update', 'client')
  quitAndInstall() {
    logger.info('[UpdaterSrv] Install update requested');
    this.app.updaterManager.quitAndInstall();
    return { success: true };
  }

  /**
   * 关闭应用并安装更新
   */
  @IPCEvent('updater:quit-and-install', 'client')
  quitAndInstallUpdate() {
    logger.info('[UpdaterSrv] Quit and install update requested');
    this.app.updaterManager.quitAndInstall();
    return { success: true };
  }
}
